// src/Component/Admin/Reusable/CustomTable.js
import React from "react";

const CustomTable = ({ cols, rows, visibleCols = {} }) => {
  const getVisible = (key) => {
    return visibleCols[key] ?? true;
  };

  return (
    <div className="overflow-x-auto">
      <table className="min-w-full text-left border border-gray-200 rounded-md">
        <thead>
          <tr className="bg-[#E1D5C9] text-[#292929]">
            {cols.map(
              (col, i) =>
                getVisible(col.key) && (
                  <th key={i} className="px-4 py-3">
                    {col.label}
                  </th>
                )
            )}
            <th className="px-4 py-3">Actions</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((row, rIndex) => (
            <tr
              key={rIndex}
              className={rIndex % 2 === 0 ? "bg-white" : "bg-[#F5EFEB]"}
            >
              {cols.map(
                (col, cIndex) =>
                  getVisible(col.key) && (
                    <td key={cIndex} className="px-4 py-3">
                      {col.render ? col.render(row[col.key], row) : row[col.key]}
                    </td>
                  )
              )}
              <td className="px-4 py-3">
                <div className="flex gap-3">
                  {row.actions || (
                    <>
                      <span className="text-gray-400">—</span>
                    </>
                  )}
                </div>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default CustomTable;
